1365	impl WalkParallel {
1366	    /// Execute the parallel recursive directory iterator. `mkf` is called
1367	    /// for each thread used for iteration. The function produced by `mkf`
1368	    /// is then in turn called for each visited file path.
1369	    pub fn run<'s, F>(self, mkf: F)
1370	    where
1371	        F: FnMut() -> FnVisitor<'s>,
1372	    {
1373	        self.visit(&mut FnBuilder { builder: mkf })
1374	    }
1375	
1376	    /// Execute the parallel recursive directory iterator using a custom
1377	    /// visitor.
1378	    ///
1379	    /// The builder given is used to construct a visitor for every thread
1380	    /// used by this traversal. The visitor returned from each builder is then
1381	    /// called for every directory entry seen by that thread.
1382	    ///
1383	    /// Typically, creating a custom visitor is useful if you need to perform
1384	    /// some kind of cleanup once traversal is finished. This can be achieved
1385	    /// by implementing `Drop` for your builder (or for your visitor, if you
1386	    /// want to execute cleanup for every thread that is launched).
1387	    ///
1388	    /// For example, each visitor might build up a data structure of results
1389	    /// corresponding to the directory entries seen for each thread. Since each
1390	    /// visitor runs on only one thread, this build-up can be done without
1391	    /// synchronization. Then, once traversal is complete, all of the results
1392	    /// can be merged together into a single data structure.
1393	    pub fn visit(mut self, builder: &mut dyn ParallelVisitorBuilder<'_>) {
1394	        let threads = self.threads();
1395	        let mut stack = vec![];
1396	        {
1397	            let mut visitor = builder.build();
1398	            let mut paths = Vec::new().into_iter();
1399	            std::mem::swap(&mut paths, &mut self.paths);
1400	            // Send the initial set of root paths to the pool of workers. Note
1401	            // that we only send directories. For files, we send to them the
1402	            // callback directly.
1403	            for path in paths {
1404	                let (dent, root_device) = if path == Path::new("-") {
1405	                    (DirEntry::new_stdin(), None)
1406	                } else {
1407	                    let root_device = if !self.same_file_system {
1408	                        None
1409	                    } else {
1410	                        match device_num(&path) {
1411	                            Ok(root_device) => Some(root_device),
1412	                            Err(err) => {
1413	                                let err = Error::Io(err).with_path(path);
1414	                                if visitor.visit(Err(err)).is_quit() {
1415	                                    return;
1416	                                }
1417	                                continue;
1418	                            }
1419	                        }
1420	                    };
1421	                    match DirEntryRaw::from_path(0, path, false) {
1422	                        Ok(dent) => {
1423	                            (DirEntry::new_raw(dent, None), root_device)
1424	                        }
1425	                        Err(err) => {
1426	                            if visitor.visit(Err(err)).is_quit() {
1427	                                return;
1428	                            }
1429	                            continue;
1430	                        }
1431	                    }
1432	                };
1433	                stack.push(Message::Work(Work {
1434	                    dent,
1435	                    ignore: self.ig_root.clone(),
1436	                    root_device,
1437	                }));
1438	            }
1439	            // ... but there's no need to start workers if we don't need them.
1440	            if stack.is_empty() {
1441	                return;
1442	            }
1443	        }
1444	        // Create the workers and then wait for them to finish.
1445	        let quit_now = Arc::new(AtomicBool::new(false));
1446	        let active_workers = Arc::new(AtomicUsize::new(threads));
1447	        let stacks = Stack::new_for_each_thread(threads, stack);
1448	        std::thread::scope(|s| {
1449	            let handles: Vec<_> = stacks
1450	                .into_iter()
1451	                .map(|stack| Worker {
1452	                    visitor: builder.build(),
1453	                    stack,
1454	                    quit_now: quit_now.clone(),
1455	                    active_workers: active_workers.clone(),
1456	                    max_depth: self.max_depth,
1457	                    min_depth: self.min_depth,
1458	                    max_filesize: self.max_filesize,
1459	                    follow_links: self.follow_links,
1460	                    skip: self.skip.clone(),
1461	                    filter: self.filter.clone(),
1462	                })
1463	                .map(|worker| s.spawn(|| worker.run()))
1464	                .collect();
1465	            for handle in handles {
1466	                handle.join().unwrap();
1467	            }
1468	        });
1469	    }
1470	
1471	    fn threads(&self) -> usize {
1472	        if self.threads == 0 {
1473	            std::thread::available_parallelism().map_or(1, |n| n.get()).min(12)
1474	        } else {
1475	            self.threads
1476	        }
1477	    }
1478	}
1479	
1480	/// Message is the set of instructions that a worker knows how to process.
1481	enum Message {
1482	    /// A work item corresponds to a directory that should be descended into.
1483	    /// Work items for entries that should be skipped or ignored should not
1484	    /// be produced.
1485	    Work(Work),
1486	    /// This instruction indicates that the worker should quit.
1487	    Quit,
1488	}
1489	
1490	/// A unit of work for each worker to process.
1491	///
1492	/// Each unit of work corresponds to a directory that should be descended
1493	/// into.
1494	struct Work {
1495	    /// The directory entry.
1496	    dent: DirEntry,
1497	    /// Any ignore matchers that have been built for this directory's parents.
1498	    ignore: Ignore,
1499	    /// The root device number. When present, only files with the same device
1500	    /// number should be considered.
1501	    root_device: Option<u64>,
1502	}
1503	
1504	#[derive(Default)]
1505	struct ReadDirResult {
1506	    entries: Vec<fs::DirEntry>,
1507	    errors: Vec<Error>,
1508	}
1509	
1510	impl Work {
1511	    /// Returns true if and only if this work item is a directory.
1512	    fn is_dir(&self) -> bool {
1513	        self.dent.is_dir()
1514	    }
1515	
1516	    /// Returns true if and only if this work item is a symlink.
1517	    fn is_symlink(&self) -> bool {
1518	        self.dent.file_type().map_or(false, |ft| ft.is_symlink())
1519	    }
1520	
1521	    /// Adds ignore rules for parent directories.
1522	    ///
1523	    /// Note that this only applies to entries at depth 0. On all other
1524	    /// entries, this is a no-op.
1525	    fn add_parents(&mut self) -> Option<Error> {
1526	        if self.dent.depth() > 0 {
1527	            return None;
1528	        }
1529	        // At depth 0, the path of this entry is a root path, so we can
1530	        // use it directly to add parent ignore rules.
1531	        let (ig, err) = self.ignore.add_parents(self.dent.path());
1532	        self.ignore = ig;
1533	        err
1534	    }
1535	
1536	    /// Adds ignore rules for this directory without reading its contents.
1537	    fn add_ignore(&mut self) {
1538	        let (ig, err) = self.ignore.add_child(self.dent.path());
1539	        self.ignore = ig;
1540	        self.dent.err = err;
1541	    }
1542	
1543	    /// Reads the directory contents of this work item and adds ignore
1544	    /// rules for this directory.
1545	    ///
1546	    /// If there was a problem with reading the directory contents, then
1547	    /// an error is returned. If there was a problem reading the ignore
1548	    /// rules for this directory, then the error is attached to this
1549	    /// work item's directory entry.
1550	    fn read_dir(&mut self) -> Result<ReadDirResult, Error> {
1551	        let readdir = match fs::read_dir(self.dent.path()) {
1552	            Ok(readdir) => readdir,
1553	            Err(err) => {
1554	                let err = Error::from(err)
1555	                    .with_path(self.dent.path())
1556	                    .with_depth(self.dent.depth());
1557	                return Err(err);
1558	            }
1559	        };
1560	        // Actually descend into the directory and read its contents
1561	        let mut result = ReadDirResult::default();
1562	        for entry in readdir {
1563	            match entry {
1564	                Ok(entry) => result.entries.push(entry),
1565	                Err(err) => result.errors.push(
1566	                    Error::from(err)
1567	                        .with_path(self.dent.path())
1568	                        .with_depth(self.dent.depth() + 1),
1569	                ),
1570	            }
1571	        }
1572	        let (ig, err) = self
1573	            .ignore
1574	            .add_child_with_entries(self.dent.path(), &result.entries);
1575	        self.ignore = ig;
1576	        self.dent.err = err;
1577	        Ok(result)
1578	    }
1579	}
1580	
1581	/// A work-stealing stack.
1582	#[derive(Debug)]
1583	struct Stack {
1584	    /// This thread's index.
1585	    index: usize,
1586	    /// The thread-local stack.
1587	    deque: Deque<Message>,
1588	    /// The work stealers.
1589	    stealers: Arc<[Stealer<Message>]>,
1590	}
1591	
1592	impl Stack {
1593	    /// Create a work-stealing stack for each thread. The given messages
1594	    /// correspond to the initial paths to start the search at. They will
1595	    /// be distributed automatically to each stack in a round-robin fashion.
1596	    fn new_for_each_thread(threads: usize, init: Vec<Message>) -> Vec<Stack> {
1597	        // Using new_lifo() ensures each worker operates depth-first, not
1598	        // breadth-first. We do depth-first because a breadth first traversal
1599	        // on wide directories with a lot of gitignores is disastrous (for
1600	        // example, searching a directory tree containing all of crates.io).
1601	        let deques: Vec<Deque<Message>> =
1602	            std::iter::repeat_with(Deque::new_lifo).take(threads).collect();
1603	        let stealers = Arc::<[Stealer<Message>]>::from(
1604	            deques.iter().map(Deque::stealer).collect::<Vec<_>>(),
1605	        );
1606	        let stacks: Vec<Stack> = deques
1607	            .into_iter()
1608	            .enumerate()
1609	            .map(|(index, deque)| Stack {
1610	                index,
1611	                deque,
1612	                stealers: stealers.clone(),
1613	            })
1614	            .collect();
1615	        // Distribute the initial messages, reverse the order to cancel out
1616	        // the other reversal caused by the inherent LIFO processing of the
1617	        // per-thread stacks which are filled here.
1618	        init.into_iter()
1619	            .rev()
1620	            .zip(stacks.iter().cycle())
1621	            .for_each(|(m, s)| s.push(m));
1622	        stacks
1623	    }
1624	
1625	    /// Push a message.
1626	    fn push(&self, msg: Message) {
1627	        self.deque.push(msg);
1628	    }
1629	
1630	    /// Pop a message.
1631	    fn pop(&self) -> Option<Message> {
1632	        self.deque.pop().or_else(|| self.steal())
1633	    }
1634	
1635	    /// Steal a message from another queue.
1636	    fn steal(&self) -> Option<Message> {
1637	        // For fairness, try to steal from index + 1, index + 2, ... len - 1,
1638	        // then wrap around to 0, 1, ... index - 1.
1639	        let (left, right) = self.stealers.split_at(self.index);
1640	        // Don't steal from ourselves
1641	        let right = &right[1..];
1642	
1643	        right
1644	            .iter()
1645	            .chain(left.iter())
1646	            .map(|s| s.steal_batch_and_pop(&self.deque))
1647	            .find_map(|s| s.success())
1648	    }
1649	}
1650	
1651	/// A worker is responsible for descending into directories, updating the
1652	/// ignore matchers, producing new work and invoking the caller's callback.
1653	///
1654	/// Note that a worker is *both* a producer and a consumer.
1655	struct Worker<'s> {
1656	    /// The caller's callback.
1657	    visitor: Box<dyn ParallelVisitor + 's>,
1658	    /// A work-stealing stack of work to do.
1659	    ///
1660	    /// We use a stack instead of a channel because a stack lets us visit
1661	    /// directories in depth first order. This can substantially reduce peak
1662	    /// memory usage by keeping both the number of file paths and gitignore
1663	    /// matchers in memory lower.
1664	    stack: Stack,
1665	    /// Whether all workers should terminate at the next opportunity. Note
1666	    /// that we need this because we don't want other `Work` to be done after
1667	    /// we quit. We wouldn't need this if have a priority channel.
1668	    quit_now: Arc<AtomicBool>,
1669	    /// The number of currently active workers.
1670	    active_workers: Arc<AtomicUsize>,
1671	    /// The maximum depth of directories to descend. A value of `0` means no
1672	    /// descension at all.
1673	    max_depth: Option<usize>,
1674	    /// The minimum depth of directories to descend.
1675	    min_depth: Option<usize>,
1676	    /// The maximum size a searched file can be (in bytes). If a file exceeds
1677	    /// this size it will be skipped.
1678	    max_filesize: Option<u64>,
1679	    /// Whether to follow symbolic links or not. When this is enabled, loop
1680	    /// detection is performed.
1681	    follow_links: bool,
1682	    /// A file handle to skip, currently is either `None` or stdout, if it's
1683	    /// a file and it has been requested to skip files identical to stdout.
1684	    skip: Option<Arc<Handle>>,
1685	    /// A predicate applied to dir entries. If true, the entry and all
1686	    /// children will be skipped.
1687	    filter: Option<Filter>,
1688	}
1689	
1690	impl<'s> Worker<'s> {
1691	    /// Runs this worker until there is no more work left to do.
1692	    ///
1693	    /// The worker will call the caller's callback for all entries that aren't
1694	    /// skipped by the ignore matcher.
1695	    fn run(mut self) {
1696	        while let Some(work) = self.get_work() {
1697	            if let WalkState::Quit = self.run_one(work) {
1698	                self.quit_now();
1699	            }
1700	        }
1701	    }
1702	
1703	    fn run_one(&mut self, mut work: Work) -> WalkState {
1704	        let should_visit = self
1705	            .min_depth
1706	            .map(|min_depth| work.dent.depth() >= min_depth)
1707	            .unwrap_or(true);
1708	
1709	        // If the work is not a directory, then we can just execute the
1710	        // caller's callback immediately and move on.
1711	        if work.is_symlink() || !work.is_dir() {
1712	            return if should_visit {
1713	                self.visitor.visit(Ok(work.dent))
1714	            } else {
1715	                WalkState::Continue
1716	            };
1717	        }
1718	        if let Some(err) = work.add_parents() {
1719	            let state = self.visitor.visit(Err(err));
1720	            if state.is_quit() {
1721	                return state;
1722	            }
1723	        }
1724	
1725	        let descend = if let Some(root_device) = work.root_device {
1726	            match is_same_file_system(root_device, work.dent.path()) {
1727	                Ok(true) => true,
1728	                Ok(false) => false,
1729	                Err(err) => {
1730	                    let state = self.visitor.visit(Err(err));
1731	                    if state.is_quit() {
1732	                        return state;
1733	                    }
1734	                    false
1735	                }
1736	            }
1737	        } else {
1738	            true
1739	        };
1740	
1741	        // Try to read the directory first before we transfer ownership
1742	        // to the provided closure. Do not unwrap it immediately, though,
1743	        // as we may receive an `Err` value e.g. in the case when we do not
1744	        // have sufficient read permissions to list the directory.
1745	        // In that case we still want to provide the closure with a valid
1746	        // entry before passing the error value.
1747	        let depth = work.dent.depth();
1748	        let readdir = if descend && self.max_depth.is_none_or(|m| depth < m) {
1749	            Some(work.read_dir())
1750	        } else {
1751	            work.add_ignore();
1752	            None
1753	        };
1754	        if should_visit {
1755	            let state = self.visitor.visit(Ok(work.dent));
1756	            if !state.is_continue() {
1757	                return state;
1758	            }
1759	        }
1760	        if !descend {
1761	            return WalkState::Skip;
1762	        }
1763	
1764	        let readdir = match readdir {
1765	            Some(readdir) => readdir,
1766	            None => return WalkState::Skip,
1767	        };
1768	        let readdir = match readdir {
1769	            Ok(readdir) => readdir,
1770	            Err(err) => {
1771	                return self.visitor.visit(Err(err));
1772	            }
1773	        };
1774	
1775	        for result in readdir.entries {
1776	            let state = self.generate_work(
1777	                &work.ignore,
1778	                depth + 1,
1779	                work.root_device,
1780	                result,
1781	            );
1782	            if state.is_quit() {
1783	                return state;
1784	            }
1785	        }
1786	        for err in readdir.errors {
1787	            let state = self.visitor.visit(Err(err));
1788	            if state.is_quit() {
1789	                return state;
1790	            }
1791	        }
1792	        WalkState::Continue
1793	    }
1794	
1795	    /// Decides whether to submit the given directory entry as a file to
1796	    /// search.
1797	    ///
1798	    /// If the entry is a path that should be ignored, then this is a no-op.
1799	    /// Otherwise, the entry is pushed on to the queue. (The actual execution
1800	    /// of the callback happens in `run_one`.)
1801	    ///
1802	    /// If an error occurs while reading the entry, then it is sent to the
1803	    /// caller's callback.
1804	    ///
1805	    /// `ig` is the `Ignore` matcher for the parent directory. `depth` should
1806	    /// be the depth of this entry. `result` should be the item yielded by
1807	    /// a directory iterator.
1808	    fn generate_work(
1809	        &mut self,
1810	        ig: &Ignore,
1811	        depth: usize,
1812	        root_device: Option<u64>,
1813	        fs_dent: fs::DirEntry,
1814	    ) -> WalkState {
1815	        let mut dent = match DirEntryRaw::from_entry(depth, &fs_dent) {
1816	            Ok(dent) => DirEntry::new_raw(dent, None),
1817	            Err(err) => {
1818	                return self.visitor.visit(Err(err));
1819	            }
1820	        };
1821	        let is_symlink = dent.file_type().map_or(false, |ft| ft.is_symlink());
1822	        if self.follow_links && is_symlink {
1823	            let path = dent.path().to_path_buf();
1824	            dent = match DirEntryRaw::from_path(depth, path, true) {
1825	                Ok(dent) => DirEntry::new_raw(dent, None),
1826	                Err(err) => {
1827	                    return self.visitor.visit(Err(err));
1828	                }
1829	            };
1830	            if dent.is_dir() {
1831	                if let Err(err) = check_symlink_loop(ig, dent.path(), depth) {
1832	                    return self.visitor.visit(Err(err));
1833	                }
1834	            }
1835	        }
1836	        // N.B. See analogous call in the single-threaded implementation about
1837	        // why it's important for this to come before the checks below.
1838	        if should_skip_entry(ig, &dent) {
1839	            return WalkState::Continue;
1840	        }
1841	        if let Some(ref stdout) = self.skip {
1842	            let is_stdout = match path_equals(&dent, stdout) {
1843	                Ok(is_stdout) => is_stdout,
1844	                Err(err) => return self.visitor.visit(Err(err)),
1845	            };
1846	            if is_stdout {
1847	                return WalkState::Continue;
1848	            }
1849	        }
1850	        let should_skip_filesize =
1851	            if self.max_filesize.is_some() && !dent.is_dir() {
1852	                skip_filesize(
1853	                    self.max_filesize.unwrap(),
1854	                    dent.path(),
1855	                    &dent.metadata().ok(),
1856	                )
1857	            } else {
1858	                false
1859	            };
1860	        let should_skip_filtered =
1861	            if let Some(Filter(predicate)) = &self.filter {
1862	                !predicate(&dent)
1863	            } else {
1864	                false
1865	            };
1866	        if !should_skip_filesize && !should_skip_filtered {
1867	            self.send(Work { dent, ignore: ig.clone(), root_device });
1868	        }
1869	        WalkState::Continue
1870	    }
1871	
1872	    /// Returns the next directory to descend into.
1873	    ///
1874	    /// If all work has been exhausted, then this returns None. The worker
1875	    /// should then subsequently quit.
1876	    fn get_work(&mut self) -> Option<Work> {
